package com.vhre.booknest.modules.author.mapper;

import com.vhre.booknest.modules.author.dto.AuthorDTO;
import com.vhre.booknest.modules.author.entity.Author;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingTarget;

import java.util.List;

/**
 * MapStruct mapper between the {@link Author} entity and its {@link AuthorDTO}.
 *
 * <p>Persistence-owned fields (id, createdAt, updatedAt) are ignored when
 * mapping DTOs into entities: they are generated by the database/audit
 * callbacks and must never be overwritten by a payload.</p>
 */
@Mapper(componentModel = "spring")
public interface AuthorMapper {

    /**
     * Converts an entity into its DTO representation.
     */
    AuthorDTO toDto(Author author);

    /**
     * Converts a list of entities into a list of DTOs.
     */
    List<AuthorDTO> toDtos(List<Author> authors);

    /**
     * Converts a DTO into a new entity (for create operations).
     */
    @Mapping(target = "id", ignore = true)
    @Mapping(target = "createdAt", ignore = true)
    @Mapping(target = "updatedAt", ignore = true)
    Author toEntity(AuthorDTO dto);

    /**
     * Updates an existing managed entity with data from a DTO (for update
     * operations), preserving the fields owned by the persistence layer.
     */
    @Mapping(target = "id", ignore = true)
    @Mapping(target = "createdAt", ignore = true)
    @Mapping(target = "updatedAt", ignore = true)
    void updateEntityFromDto(AuthorDTO dto, @MappingTarget Author author);
}
